using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShopLocation", menuName = "Data/Map/Shop Location")]
public class ShopLocation : Location
{
	public enum ShopEnum
	{
		FORGE,
		SENTINEL,
		EPIC
	}

	[Header("Rewards")]
	[SerializeField]
	private ClearingReward clearingReward;

	[SerializeField]
	private ShopEnum shopEnum;

	public override NodeData GetNodeData()
	{
		NodeData nodeData = new NodeData();
		if (shopEnum == ShopEnum.FORGE && ReferenceSingleton<RunModifiersManager>.Instance.BrokenForgeRunModifierClearingReward != null)
		{
			if (ReferenceSingleton<RunModifiersManager>.Instance.MysteriousAdventureRunModifier != null)
			{
				return ReferenceSingleton<RunModifiersManager>.Instance.MysteriousAdventureRunModifier.GetCurrentEventLocation().GetNodeData();
			}
			nodeData.NodeEnum = NodeEnum.REWARD;
			nodeData.Reward = ReferenceSingleton<RunModifiersManager>.Instance.BrokenForgeRunModifierClearingReward.name;
		}
		else
		{
			nodeData.NodeEnum = NodeEnum.SHOP;
			nodeData.Reward = clearingReward.name;
		}
		return nodeData;
	}
}
